examples.template:
MonarchNotificationsBell(unreadCount: {{unreadCount}}) {
    showsNotifications = true
}
.sheet(isPresented: $showsNotifications) {
    NavigationStack {
        MonarchNotificationCenter(
            items,
            now: {{now|date}},
            onMarkRead: { id in read.insert(id) },
            onMarkAllRead: { read = Set(items.map(\.id)) }
        ) {
            Button({{seeAll}}) {}
                .buttonStyle(.monarchLink(.inline))
        }
    }
    .environment(\.timeZone, .gmt)
}

examples.setupTemplate:
@State private var read: Set<String> = []
@State private var showsNotifications = false

private let source = [
    MonarchNotificationCenterItem(
        id: {{items.0.id}},
        title: {{items.0.title}},
        time: {{items.0.time|date}},
        actorName: {{items.0.actor}}
    ),
    MonarchNotificationCenterItem(
        id: {{items.1.id}},
        title: {{items.1.title}},
        message: {{items.1.description}},
        time: {{items.1.time|date}},
        actorName: {{items.1.actor}}
    ),
    MonarchNotificationCenterItem(
        id: {{items.2.id}},
        title: {{items.2.title}},
        time: {{items.2.time|date}},
        isRead: {{items.2.read}}
    ),
]

private var items: [MonarchNotificationCenterItem] {
    source.map {
        MonarchNotificationCenterItem(
            id: $0.id,
            title: $0.title,
            message: $0.message,
            time: $0.time,
            isRead: $0.isRead || read.contains($0.id),
            actorName: $0.actorName
        )
    }
}

